-- Adopt sorcery-registry stable identifiers.
--
-- Upstream slugs are mutable: the 2026 set renumbering rewrote every one of
-- them (alp-detonate-b-s -> 001-detonate-b-s), which broke every lookup keyed
-- on a slug. The registry (github.com/sadkinglabs/sorcery-registry) assigns an
-- id per card (codex_id) and per physical printing (printing_id) that are
-- guaranteed never to change, so we key on those instead and demote slug to a
-- display/legacy column.
--
-- Both columns are nullable: printings the registry does not cover (or that we
-- carry and it does not) simply stay NULL and fall back to slug/name lookups.

-- AlterTable
ALTER TABLE "public"."Card" ADD COLUMN     "codexId" TEXT;

-- AlterTable
ALTER TABLE "public"."Variant" ADD COLUMN     "printingId" TEXT;

-- CreateIndex
CREATE INDEX "Card_codexId_idx" ON "public"."Card"("codexId");

-- CreateIndex
CREATE UNIQUE INDEX "Variant_printingId_key" ON "public"."Variant"("printingId");

-- CreateIndex
CREATE INDEX "Variant_printingId_idx" ON "public"."Variant"("printingId");

